import type { SidebarsConfig } from '@docusaurus/plugin-content-docs';
import fs from 'fs';
import path from 'path';

/**
 * Sidebars configuration.
 *
 * The `apiSidebar` is auto-generated by `npm run docs:sync` and written to
 * `sidebars-generated.json`. If that file exists, we merge it in so the
 * Components / Layouts / Blocks / Tokens / Hooks sections are always in sync
 * with the Foundation source code.
 *
 * Fall back to a minimal static config when the generated file is absent
 * (e.g. fresh clone before the first `docs:sync` run).
 */
const generatedPath = path.join(__dirname, 'sidebars-generated.json');

let generated: SidebarsConfig = {};
if (fs.existsSync(generatedPath)) {
  try {
    generated = JSON.parse(fs.readFileSync(generatedPath, 'utf-8')) as SidebarsConfig;
  } catch {
    // ignore parse errors — use defaults below
  }
}

const sidebars: SidebarsConfig = {
  // ── Guides sidebar (always static) ────────────────────────────────────────
  tutorialSidebar: generated.tutorialSidebar ?? [
    'intro',
    {
      type: 'category',
      label: 'Guides',
      collapsed: false,
      items: [
        'guides/getting-started',
        'guides/theming',
        'guides/tokens',
        'guides/components',
        'guides/layouts',
        'guides/web',
      ],
    },
    'contributing',
  ],

  // ── API Reference sidebar (auto-generated or minimal static fallback) ──────
  apiSidebar: generated.apiSidebar ?? [
    'api/intro',
  ],
};

export default sidebars;
